#include <cctype>
#include <string>

namespace
{
    std::string upper(std::string s) { for (char& c : s) c = static_cast<char>(std::toupper(static_cast<unsigned char>(c))); return s; }

    std::string extensionOf(const std::string& name)
    {
        const auto dot{ name.rfind('.') };
        return dot == std::string::npos || dot == 0 ? "" : name.substr(dot);
    }

    bool reserved(const std::string& name)
    {
        const auto dot{ name.find('.') };
        const std::string base{ upper(dot == std::string::npos ? name : name.substr(0, dot)) };
        if (base == "CON" || base == "PRN" || base == "AUX" || base == "NUL") return true;
        return base.size() == 4 && (base.rfind("COM", 0) == 0 || base.rfind("LPT", 0) == 0) && base[3] >= '1' && base[3] <= '9';
    }
}

std::string fileNameProblem(const std::string& name)
{
    if (name.empty()) return "Enter a name.";
    for (char c : name)
        if (static_cast<unsigned char>(c) < 32 || std::string("\\/:*?\"<>|").find(c) != std::string::npos)
            return "A name cannot contain \\ / : * ? \" < > |";
    if (name.back() == ' ' || name.back() == '.') return "A name cannot end with a space or a dot.";
    if (reserved(name)) return "That name is reserved by Windows.";
    if (name.size() > 255) return "The name is too long.";
    return "";
}

std::string applyRename(const std::string& oldName, const std::string& newName, bool keepExtension)
{
    if (!keepExtension) return newName;
    const std::string ext{ extensionOf(oldName) };
    if (ext.empty()) return newName;
    if (newName.size() >= ext.size() && upper(newName.substr(newName.size() - ext.size())) == upper(ext)) return newName;
    return newName + ext;
}

unitTests:
const std::string bad = "A name cannot contain \\ / : * ? \" < > |";
TEST("good names") { CHECK_EQ(fileNameProblem("notes.txt"), std::string("")); CHECK_EQ(fileNameProblem(".gitignore"), std::string("")); CHECK_EQ(fileNameProblem("CONSOLE.log"), std::string("")); CHECK_EQ(fileNameProblem("com0"), std::string("")); }
TEST("problems") {
    CHECK_EQ(fileNameProblem(""), std::string("Enter a name.")); CHECK_EQ(fileNameProblem("a:b"), bad); CHECK_EQ(fileNameProblem("tab\there"), bad);
    CHECK_EQ(fileNameProblem("final. "), std::string("A name cannot end with a space or a dot.")); CHECK_EQ(fileNameProblem("v2."), std::string("A name cannot end with a space or a dot."));
    CHECK_EQ(fileNameProblem("con.txt"), std::string("That name is reserved by Windows.")); CHECK_EQ(fileNameProblem("Lpt3"), std::string("That name is reserved by Windows."));
    CHECK_EQ(fileNameProblem(std::string(256, 'a')), std::string("The name is too long.")); CHECK_EQ(fileNameProblem(std::string(255, 'a')), std::string(""));
}
TEST("the order of checks") { CHECK_EQ(fileNameProblem("con?"), bad); CHECK_EQ(fileNameProblem("nul."), std::string("A name cannot end with a space or a dot.")); }
TEST("keeping the extension") {
    CHECK_EQ(applyRename("notes.txt", "ideas", true), std::string("ideas.txt")); CHECK_EQ(applyRename("notes.txt", "ideas.TXT", true), std::string("ideas.TXT"));
    CHECK_EQ(applyRename("notes.txt", "ideas.md", true), std::string("ideas.md.txt")); CHECK_EQ(applyRename("notes.txt", "ideas", false), std::string("ideas"));
    CHECK_EQ(applyRename(".gitignore", "rules", true), std::string("rules")); CHECK_EQ(applyRename("archive.tar.gz", "backup", true), std::string("backup.gz"));
}

